import fs from 'fs/promises';
import path from 'path';
import { z } from 'zod';
import {
  GuidanceSourceSchema,
  GuidanceSourceCreateSchema,
} from '../../types/guidance-source';

interface SourceRequestInput {
  action: 'add' | 'update';
  sourceFile?: string;
  isRemovingSource: boolean;
  hasContent: boolean;
  title?: string;
}

export const contextSourceRequest = async (input: SourceRequestInput) => {
  const { action, sourceFile, isRemovingSource, title } = input;
  if (!sourceFile && !isRemovingSource) return undefined;
  if (
    input.hasContent ||
    (sourceFile && isRemovingSource) ||
    (action === 'update' && title !== undefined)
  )
    throw new z.ZodError([
      {
        code: 'custom',
        path: ['source'],
        message:
          'Configure a source separately from file, references, title and verifier updates',
      },
    ]);
  if (isRemovingSource)
    return { method: 'DELETE', suffix: '/source', body: undefined };
  const file = path.resolve(z.string().min(1).parse(sourceFile));
  const raw = z
    .record(z.string(), z.unknown())
    .parse(JSON.parse(await fs.readFile(file, 'utf8')));
  if (raw.kind === 'file' && typeof raw.path === 'string')
    raw.path = path.resolve(path.dirname(file), raw.path);
  const source = GuidanceSourceSchema.parse(raw);
  return action === 'add'
    ? {
        method: 'POST',
        suffix: '',
        body: GuidanceSourceCreateSchema.parse({ title, source }),
      }
    : { method: 'PUT', suffix: '/source', body: { source } };
};
